}

class _FakeAnalyticsTransport implements AnalyticsTransport {
  _FakeAnalyticsTransport({this.responder});

  final List<_RecordedRequest> requests = [];

  /// Return a status code, or throw an exception to simulate transport failure.
  int Function(int callNumber)? responder;

  int _callCount = 0;

  @override
  Future<int> postEvent(
    Uri url,
    Map<String, String> headers,
    String body,
  ) async {
    _callCount += 1;
    requests.add(_RecordedRequest(url, headers, body));
    final fn = responder;
    if (fn == null) return 200;
    return fn(_callCount);
  }
}

class _ThrowingTransport implements AnalyticsTransport {
  _ThrowingTransport({required this.failuresBeforeSuccess});

  int callCount = 0;
  final int failuresBeforeSuccess;

  @override
  Future<int> postEvent(
    Uri url,
    Map<String, String> headers,
    String body,
  ) async {
    callCount += 1;
    if (callCount <= failuresBeforeSuccess) {
      throw const SocketException('boom');
    }
    return 200;
  }
