      expect(await repo.track('a'), isTrue);
      expect(await repo.track('b'), isTrue);
      // Not yet at threshold.
      await Future<void>.delayed(Duration.zero);
      expect(transport.requests.length, lessThan(2));

      expect(await repo.track('c'), isTrue);
      // Allow the unawaited drain to complete.
      await repo.flush();

      expect(transport.requests.length, 3);
      expect(repo.bufferLength, 0);
      await repo.dispose();
    });

    test('flushes by timer when buffer is below batch size', () async {
      final transport = _FakeAnalyticsTransport();
      final repo = AnalyticsRepository(
        transport: transport,
        flushBatchSize: 50,
        flushInterval: const Duration(milliseconds: 50),
        sleep: (_) async {},
      );

      await repo.track('a');
      await repo.track('b');

      // Wait for the timer to fire.
      await Future<void>.delayed(const Duration(milliseconds: 200));
      await repo.flush();

      expect(transport.requests.length, 2);
      await repo.dispose();
    });

    test('explicit flush() drains all events', () async {
      final transport = _FakeAnalyticsTransport();
      final repo = AnalyticsRepository(
        transport: transport,
        flushBatchSize: 100,
        flushInterval: const Duration(seconds: 30),
        sleep: (_) async {},
